class Sheet {
  private grid: number[][];
  constructor(rows: number) {
    this.grid = Array.from({ length: rows }, () => new Array(26).fill(0));
  }
  private pos(cell: string): [number, number] {
    return [Number(cell.slice(1)) - 1, cell.charCodeAt(0) - 65];
  }
  setCell(cell: string, value: number): void {
    const [r, c] = this.pos(cell);
    this.grid[r][c] = value;
  }
  resetCell(cell: string): void {
    this.setCell(cell, 0);
  }
  getValue(formula: string): number {
    const term = (t: string) => {
      if (t[0] >= "A" && t[0] <= "Z") { const [r, c] = this.pos(t); return this.grid[r][c]; }
      return Number(t);
    };
    const [x, y] = formula.slice(1).split("+");
    return term(x) + term(y);
  }
}

